    areset = 0; #10; // Deassert reset
    if (q !== 4'b0000) begin
        $display("MISMATCH: cycle=%0d time=%0t signal=q expected=%h actual=%h", cycle_count, $time, 4'b0000, q);
        errors = errors + 1;
    end

    // Test loading data
    data = 4'b1010; // Load data
    load = 1; ena = 0; #10; // Load data into shift register
    load = 0; // Deassert load
    if (q !== data) begin
        $display("MISMATCH: cycle=%0d time=%0t signal=q expected=%h actual=%h", cycle_count, $time, data, q);
        errors = errors + 1;
    end

    // Test shifting functionality
    ena = 1; #10; // Enable shifting
    if (q !== {1'b0, data[3:1]}) begin
        $display("MISMATCH: cycle=%0d time=%0t signal=q expected=%h actual=%h", cycle_count, $time, {1'b0, data[3:1]}, q);
        errors = errors + 1;
    end

    // Test multiple shifts
    #10; // Shift again
    if (q !== {1'b0, {1'b0, data[3:1]}[3:1]}) begin
        $display("MISMATCH: cycle=%0d time=%0t signal=q expected=%h actual=%h", cycle_count, $time, {1'b0, {1'b0, data[3:1]}[3:1]}, q);
        errors = errors + 1;
    end

    // Test load priority over shift
    data = 4'b1111; // New data
    load = 1; #10; // Load new data while shifting is enabled
    if (q !== data) begin
        $display("MISMATCH: cycle=%0d time=%0t signal=q expected=%h actual=%h", cycle_count, $time, data, q);
        errors = errors + 1;
    end

    // Test reset during operation
    load = 0; ena = 1; #10; // Enable shifting
    areset = 1; #10; // Assert reset
    if (q !== 4'b0000) begin
        $display("MISMATCH: cycle=%0d time=%0t signal=q expected=%h actual=%h", cycle_count, $time, 4'b0000, q);
        errors = errors + 1;
    end

    // Test edge case: all zeros
    data = 4'b0000; load = 1; #10; // Load zeros
    load = 0; ena = 1; #10; // Shift
    if (q !== 4'b0000) begin
        $display("MISMATCH: cycle=%0d time=%0t signal=q expected=%h actual=%h", cycle_count, $time, 4'b0000, q);
        errors = errors + 1;
    end

    // Test edge case: all ones
    data = 4'b1111; load = 1; #10; // Load ones
    load = 0; ena = 1; #10; // Shift
    if (q !== 4'b0111) begin
        $display("MISMATCH: cycle=%0d time=%0t signal=q expected=%h actual=%h", cycle_count, $time, 4'b0111, q);
        errors = errors + 1;
    end

    // Final report
    if (errors == 0) begin
        $display("All tests passed!");
    end else begin
        $display("%d errors found.", errors);
    end
end
